import json
p='/home/runner/.shurik/state/igor-makarov/beetle-in-the-anthill/friends-4/pi-jsonl/sessions/4-74/main.jsonl'
for line in open(p):
    try: d=json.loads(line)
    except: continue
    s=json.dumps(d)
    if 'push' in s:
        # find command fields recursively
        def walk(o):
            if isinstance(o,dict):
                for k,v in o.items():
                    if k=='command' and isinstance(v,str) and 'push' in v:
                        print('CMD:',v[:400]); print('---')
                    walk(v)
            elif isinstance(o,list):
                for v in o: walk(v)
        walk(d)
EOF
